scripts:
Chart.defaults.font.family = "'Segoe UI','Helvetica Neue',Arial,sans-serif";
Chart.defaults.color = '#5b6472';

new Chart(document.getElementById('toneChart'), {
  type: 'line',
  data: {
    labels: ['Q1 FY24','Q2 FY24','Q3 FY24','Q4 FY24','Q1 FY25','Q2 FY25','Q3 FY25','Q4 FY25','Q1 FY26','Q2 FY26','Q3 FY26','Q4 FY26'],
    datasets: [{
      label: 'Puntaje de confianza de la gerencia (1–10, juicio cualitativo)',
      data: [6,6,6,6,6,6,7,8,7,8,9,9],
      borderColor: '#1a56db',
      backgroundColor: '#1a56db',
      tension: 0.3,
      pointRadius: 5,
      pointBackgroundColor: (ctx) => [3,8].includes(ctx.dataIndex) ? '#c22' : '#1a56db'
    }]
  },
  options: {
    plugins: {
      legend: { position:'bottom', labels:{font:{size:11}} },
      title: { display:true, text:'Evolución del tono (confianza) de la gerencia por trimestre — puntos rojos: puntos de inflexión clave (divulgación de ciberseguridad en Q4 FY24 / reconocimiento franco de la CFO en Q1 FY26)', font:{size:11.5} }
    },
    scales: { y: { min:0, max:10, ticks:{stepSize:2} } }
  }
});
